import AutoGradeCore
import CoreGraphics
import Foundation
import ImageIO
import XCTest

/// Reads fixtures/ (generated by research/make_fixtures.py). Every loader
/// checks the manifest's shape and sha256, so a stale or hand-edited fixture
/// fails loudly instead of being compared against.
enum Fixtures {
    static let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        .deletingLastPathComponent().appendingPathComponent("fixtures")

    struct Entry: Decodable {
        let file: String
        let dtype: String
        let shape: [Int]
        let sha256: String
    }

    struct CropCase: Decodable {
        let name: String
        let input: String
        let transposed: Bool
        let origin: [Float]
        let length: [Float]
        let output: [Int]
    }

    struct Manifest: Decodable {
        let files: [String: Entry]
        let synthetic_shots: [[Int]]
        let cut_threshold: Float
        let vfr_frame_times: [Double]
        let crop_cases: [CropCase]
        let overlay_cases: [OverlayCase]
        let background_cases: [BackgroundCase]
    }

    struct BackgroundCase: Decodable {
        let name: String
        let effect: String
        let sigma: Float
        let colour: [Float]
    }

    struct OverlayCase: Decodable {
        let name: String
        let origin: [Int32]
    }

    static let manifest: Manifest = {
        let data = try! Data(contentsOf: root.appendingPathComponent("manifest.json"))
        return try! JSONDecoder().decode(Manifest.self, from: data)
    }()

    static func url(_ name: String) -> URL { root.appendingPathComponent(manifest.files[name]!.file) }

    private static func checkedData(_ name: String) throws -> (Data, Entry) {
        let entry = try XCTUnwrap(manifest.files[name], "fixture \(name) not in manifest")
        let data = try Data(contentsOf: root.appendingPathComponent(entry.file))
        XCTAssertEqual(sha256(data), entry.sha256, "fixture \(name) does not match manifest; regenerate fixtures")
        return (data, entry)
    }

    static func floats(_ name: String) throws -> (values: [Float], shape: [Int]) {
        let (data, entry) = try checkedData(name)
        XCTAssertEqual(entry.dtype, "float32")
        let values = data.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        XCTAssertEqual(values.count, entry.shape.reduce(1, *))
        return (values, entry.shape)
    }

    static func bytes(_ name: String) throws -> (values: [UInt8], shape: [Int]) {
        let (data, entry) = try checkedData(name)
        XCTAssertEqual(entry.dtype, "uint8")
        return ([UInt8](data), entry.shape)
    }

    static func text(_ name: String) throws -> Data { try checkedData(name).0 }

    /// 8-bit RGB PNG -> (width, height, interleaved RGB). Reads the decoded
    /// samples straight from the CGImage provider: no colour management.
    static func rgb8(_ name: String) throws -> (width: Int, height: Int, rgb: [UInt8]) {
        let (data, entry) = try checkedData(name)
        let source = try XCTUnwrap(CGImageSourceCreateWithData(data as CFData, nil))
        let image = try XCTUnwrap(CGImageSourceCreateImageAtIndex(source, 0, nil))
        let raw = try XCTUnwrap(image.dataProvider?.data) as Data
        let w = image.width, h = image.height, bpp = image.bitsPerPixel / 8, row = image.bytesPerRow
        XCTAssertEqual(image.bitsPerComponent, 8)
        XCTAssertEqual(entry.shape, [h, w, 3])
        var rgb = [UInt8](repeating: 0, count: w * h * 3)
        raw.withUnsafeBytes { (p: UnsafeRawBufferPointer) in
            for y in 0..<h {
                for x in 0..<w {
                    for c in 0..<3 { rgb[(y * w + x) * 3 + c] = p[y * row + x * bpp + c] }
                }
            }
        }
        return (w, h, rgb)
    }

    /// 8-bit RGB PNG -> planar float /255, the fixture input convention.
    static func planarImage(_ name: String, kernels: GradeKernels) throws -> PlanarImage {
        let (w, h, rgb) = try rgb8(name)
        let n = w * h
        var planar = [Float](repeating: 0, count: 3 * n)
        for i in 0..<n {
            for c in 0..<3 { planar[c * n + i] = Float(rgb[i * 3 + c]) / 255 }
        }
        return try kernels.makeImage(width: w, height: h, floats: planar)
    }

    static func aiLUT(_ prefix: String, kernels: GradeKernels) throws -> AiLUT {
        try kernels.makeAiLUT(lut: try floats("\(prefix)_lut").values, vertices: try floats("\(prefix)_vertices").values,
                              size: 33)
    }
}

/// Compare a planar float image, quantized with the shared rule, against an 8-bit PNG.
func lsbDifference(_ img: PlanarImage, _ png: String) throws -> (max: Int, differing: Int, pixels: Int) {
    let (w, h, rgb) = try Fixtures.rgb8(png)
    XCTAssertEqual(img.width, w)
    XCTAssertEqual(img.height, h)
    let f = img.floats(), n = w * h
    var worst = 0, differing = 0
    for i in 0..<n {
        var any = false
        for c in 0..<3 {
            let d = abs(Int(quantize8(f[c * n + i])) - Int(rgb[i * 3 + c]))
            worst = max(worst, d)
            any = any || d > 0
        }
        if any { differing += 1 }
    }
    return (worst, differing, n)
}

func maxAbsDifference(_ a: [Float], _ b: [Float]) -> Float {
    precondition(a.count == b.count)
    var worst: Float = 0
    for i in 0..<a.count { worst = max(worst, abs(a[i] - b[i])) }
    return worst
}

import CryptoKit
func sha256(_ data: Data) -> String {
    SHA256.hash(data: data).map { String(format: "%02x", $0) }.joined()
}
